def regex_search(pattern: str, text: str) -> bool:
    n = len(text)

    class State:
        __slots__ = ('trans',)
        def __init__(self):
            self.trans = []

    class Frag:
        __slots__ = ('start', 'end', 'is_assertion')
        def __init__(self, start, end, is_assertion=False):
            self.start = start
            self.end = end
            self.is_assertion = is_assertion

    pos = [0]

    def new_state():
        return State()

    def parse_element():
        c = pattern[pos[0]]
        if c == '.':
            pos[0] += 1
            s0, s1 = new_state(), new_state()
            s0.trans.append(('d', None, s1))
            return Frag(s0, s1)
        elif c == '\\':
            pos[0] += 1
            if pos[0] >= len(pattern):
                raise ValueError("trailing backslash")
            c2 = pattern[pos[0]]
            pos[0] += 1
            s0, s1 = new_state(), new_state()
            s0.trans.append(('c', c2, s1))
            return Frag(s0, s1)
        elif c == '[':
            return parse_class()
        elif c == '(':
            pos[0] += 1
            inner = parse_alternative()
            if pos[0] >= len(pattern) or pattern[pos[0]] != ')':
                raise ValueError("unmatched (")
            pos[0] += 1
            s0, s1 = new_state(), new_state()
            s0.trans.append(('e', None, inner.start))
            inner.end.trans.append(('e', None, s1))
            return Frag(s0, s1)
        elif c == '^':
            pos[0] += 1
            s0, s1 = new_state(), new_state()
            s0.trans.append(('sa', None, s1))
            return Frag(s0, s1, True)
        elif c == '$':
            pos[0] += 1
            s0, s1 = new_state(), new_state()
            s0.trans.append(('ea', None, s1))
            return Frag(s0, s1, True)
        elif c in ('*', '+', '?', '|', ')'):
            raise ValueError("invalid character in pattern")
        else:
            pos[0] += 1
            s0, s1 = new_state(), new_state()
            s0.trans.append(('c', c, s1))
            return Frag(s0, s1)

    def parse_class():
        pos[0] += 1
        negate = False
        if pos[0] < len(pattern) and pattern[pos[0]] == '^':
            negate = True
            pos[0] += 1
        items = []
        while pos[0] < len(pattern) and pattern[pos[0]] != ']':
            if pattern[pos[0]] == '\\':
                pos[0] += 1
                if pos[0] >= len(pattern):
                    raise ValueError("trailing backslash")
                lo = pattern[pos[0]]
                pos[0] += 1
            else:
                lo = pattern[pos[0]]
                pos[0] += 1
            if (pos[0] < len(pattern) and pattern[pos[0]] == '-'
                    and pos[0] + 1 < len(pattern) and pattern[pos[0] + 1] != ']'):
                pos[0] += 1
                if pos[0] < len(pattern) and pattern[pos[0]] == '\\':
                    pos[0] += 1
                    if pos[0] >= len(pattern):
                        raise ValueError("trailing backslash")
                    hi = pattern[pos[0]]
                    pos[0] += 1
                else:
                    hi = pattern[pos[0]]
                    pos[0] += 1
                if ord(lo) > ord(hi):
                    raise ValueError("invalid range")
                items.append((lo, hi))
            else:
                items.append((lo, lo))
        if pos[0] >= len(pattern):
            raise ValueError("unmatched [")
        pos[0] += 1
        if not items:
            raise ValueError("empty character class")
        def matcher(ch):
            for lo, hi in items:
                if ord(lo) <= ord(ch) <= ord(hi):
                    return not negate
            return negate
        s0, s1 = new_state(), new_state()
        s0.trans.append(('cl', matcher, s1))
        return Frag(s0, s1)

    def parse_concat():
        frags = []
        while pos[0] < len(pattern) and pattern[pos[0]] not in ('|', ')'):
            frag = parse_element()
            if pos[0] < len(pattern) and pattern[pos[0]] in ('*', '+', '?'):
                if frag.is_assertion:
                    raise ValueError("quantifier on assertion")
                q = pattern[pos[0]]
                pos[0] += 1
                if pos[0] < len(pattern) and pattern[pos[0]] in ('*', '+', '?'):
                    raise ValueError("double quantifier")
                if q == '*':
                    s0, s1 = new_state(), new_state()
                    s0.trans.append(('e', None, frag.start))
                    s0.trans.append(('e', None, s1))
                    frag.end.trans.append(('e', None, frag.start))
                    frag.end.trans.append(('e', None, s1))
                    frag = Frag(s0, s1)
                elif q == '+':
                    s1 = new_state()
                    frag.end.trans.append(('e', None, frag.start))
                    frag.end.trans.append(('e', None, s1))
                    frag = Frag(frag.start, s1)
                elif q == '?':
                    s0, s1 = new_state(), new_state()
                    s0.trans.append(('e', None, frag.start))
                    s0.trans.append(('e', None, s1))
                    frag.end.trans.append(('e', None, s1))
                    frag = Frag(s0, s1)
            frags.append(frag)
        if not frags:
            s0, s1 = new_state(), new_state()
            s0.trans.append(('e', None, s1))
            return Frag(s0, s1)
        result = frags[0]
        for i in range(1, len(frags)):
            result.end.trans.append(('e', None, frags[i].start))
            result = Frag(result.start, frags[i].end)
        return result

    def parse_alternative():
        left = parse_concat()
        while pos[0] < len(pattern) and pattern[pos[0]] == '|':
            pos[0] += 1
            right = parse_concat()
            s0, s1 = new_state(), new_state()
            s0.trans.append(('e', None, left.start))
            s0.trans.append(('e', None, right.start))
            left.end.trans.append(('e', None, s1))
            right.end.trans.append(('e', None, s1))
            left = Frag(s0, s1)
        return left

    frag = parse_alternative()
    if pos[0] != len(pattern):
        raise ValueError("unmatched )")

    start = frag.start
    end = frag.end

    def eps_closure(states, p):
        result = set()
        stack = list(states)
        for s in states:
            result.add(s)
        while stack:
            s = stack.pop()
            for (ttype, data, target) in s.trans:
                if ttype == 'e':
                    if target not in result:
                        result.add(target)
                        stack.append(target)
                elif ttype == 'sa':
                    if p == 0 and target not in result:
                        result.add(target)
                        stack.append(target)
                elif ttype == 'ea':
                    if p == n and target not in result:
                        result.add(target)
                        stack.append(target)
        return result

    current = eps_closure({start}, 0)
    if end in current:
        return True

    for i in range(n):
        next_states = set()
        for s in current:
            for (ttype, data, target) in s.trans:
                if ttype == 'c':
                    if text[i] == data:
                        next_states.add(target)
                elif ttype == 'd':
                    next_states.add(target)
                elif ttype == 'cl':
                    if data(text[i]):
                        next_states.add(target)
        next_states.add(start)
        current = eps_closure(next_states, i + 1)
        if end in current:
            return True

    return False
